<?php declare(strict_types=1);
/** Memory-only bookkeeping and fake transport callbacks; never sends mail. */
require __DIR__.'/../src/bootstrap.php';
use Kulturhus\Verein\{Database,Registry,Finance,Settings,SettingsSchema,ContributionInvoices,ContributionReminders};
$n=0;function ok(bool $v,string $label):void{global $n;if(!$v)throw new RuntimeException($label);++$n;echo "PASS $label\n";}
function denied(callable $f,string $label):void{try{$f();}catch(DomainException){ok(true,$label);return;}throw new RuntimeException('Not denied: '.$label);}
$key=static fn()=>bin2hex(random_bytes(16));
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);Database::migrate($db);
$db->exec("INSERT INTO clubs VALUES('a','Synthetic A'),('b','Synthetic B');INSERT INTO actors(id,club_id,role) VALUES('manager','a','members'),('queue','a','members'),('reader','a','member'),('member','a','member'),('foreign','b','treasurer'),('finance-only','a','treasurer');INSERT INTO actor_capabilities VALUES('manager','local_finance'),('queue','local_finance')");
$settings=new Settings($db,'manager');$role=$settings->saveRole('',0,['name'=>'Finance reader','members_access'=>'none','finance_access'=>'read','settings_access'=>false]);$settings->assignRole('reader',$role,0);
$settings->save('club',array_replace(SettingsSchema::defaults('club'),['name'=>'Musterverein','street'=>'Testweg 1','postcode'=>'00000','city'=>'Musterort']),0);
$settings->save('bank',array_replace(SettingsSchema::defaults('bank'),['account_id'=>(new Finance($db,'manager'))->createAccount('Invoice bank','offline','0','2026-01-01'),'holder'=>'Musterverein','iban'=>'DE89370400440532013000']),0);
foreach(['single','payer','child','unlinked-family','late'] as $i=>$person){$db->prepare("INSERT INTO contacts(id,club_id,kind,name,email,address) VALUES(?,'a','person',?,?,?)")->execute([$person,'Test '.$person,$person.'@example.invalid','Testweg 2, 00000 Musterort']);$db->prepare("INSERT INTO memberships(id,club_id,contact_id,member_number,status,starts_on) VALUES(?,'a',?,?,'aktiv',?)")->execute(['m-'.$person,$person,'T'.($i+1),$person==='late'?'2026-02-01':'2025-01-01']);}
$registry=new Registry($db,'manager');$registry->assignFamily('payer','','new','Synthetische Familie');$family=$registry->family('payer');$registry->assignFamily('child','',$family['id']);
$db->prepare("INSERT INTO membership_applications(id,club_id,request_key,status,answers,configuration,consent_snapshot,configuration_version,submitted_at,reviewed_at,reviewed_by,contact_id) VALUES('family-app','a',?,'accepted',?,'{}','{}',1,'2025-12-01','2025-12-02','manager','unlinked-family')")->execute([$key(),json_encode(['membership_type'=>'family_member'])]);
$worker=new ContributionReminders($db,'manager');$finance=new Finance($db,'manager');
denied(fn()=>(new ContributionReminders($db,'member'))->preview('2026-01-01'),'ordinary member cannot inspect financial run');
$read=new ContributionReminders($db,'reader');ok(count($read->preview('2026-01-01')['annual_candidates'])===2,'read-only finance may preview exactly the payers');
denied(fn()=>$read->run('2026-01-01',true),'read-only finance cannot execute');
ok((new ContributionReminders($db,'foreign'))->preview('2026-01-01')['annual_candidates']===[],'annual candidates are club isolated');
$preview=$worker->run('2026-01-01');
ok(!$preview['executed']&&$preview['created']===0&&$preview['queued']===0,'run defaults to dry-run');
ok(array_column($preview['annual_candidates'],'contact_id')===['payer','single'],'annual run excludes family children, unlinked family members and later joins');
ok((int)$db->query('SELECT COUNT(*) FROM finance_entries')->fetchColumn()===0,'dry-run leaves bookkeeping untouched');
ok($worker->preview('2026-01-02')['annual_candidates']===[],'annual creation only due on January first');
$run=$worker->run('2026-01-01',true);
ok($run['created']===2&&$run['queued']===2&&$run['errors']===[],'January run creates two issued invoices and private deliveries');
$single=$db->query("SELECT entry_id FROM member_dues_people WHERE contact_id='single' AND year=2026")->fetchColumn();$payer=$db->query("SELECT entry_id FROM member_dues_people WHERE contact_id='payer' AND year=2026")->fetchColumn();
ok($db->query("SELECT entry_id FROM member_dues_people WHERE contact_id='child' AND year=2026")->fetchColumn()===$payer,'family shares the payer invoice');
ok($finance->entry($single)['amount_cents']===4800&&$finance->entry($payer)['amount_cents']===7200,'annual single and family prices are preserved');
ok($finance->entry($single)['document_date']==='2026-01-01'&&$finance->entry($single)['due_date']==='2026-02-01','annual due date is one calendar month after issue');
ok((new Finance($db,'finance-only'))->createAnnualContribution('single',2026,'','2026-01-01')===$single,'finance-only role can operate annual dues without member-management access');
$again=$worker->run('2026-01-01',true);ok($again['created']===0&&$again['queued']===0&&(int)$db->query('SELECT COUNT(*) FROM contribution_deliveries')->fetchColumn()===2,'repeated January run does not duplicate invoices or deliveries');
foreach(['APP_URL','APP_ENV','VEREIN_MODE','KULTURHUS_DISABLE_MAIL','KULTURHUS_LOCAL_DEMO'] as $env)putenv($env);
putenv('VEREIN_MODE=synthetic');$calls=[];$fake=static function($to,$subject,$text,$html,$attachments)use(&$calls,$db){$calls[]=compact('to','subject','text','html','attachments');return true;};
ok($worker->dispatch('https://verein.example.invalid',$fake,'2026-01-01')===0&&$calls===[],'synthetic PC never invokes transport even for pending invoices');
putenv('VEREIN_MODE');putenv('APP_URL=http://127.0.0.1:8092');ok($worker->dispatch('https://verein.example.invalid',$fake,'2026-01-01')===0,'local application URL blocks mail even with public delivery URL');putenv('APP_URL');
ok($worker->dispatch('https://verein.example.invalid',$fake,'2026-01-01')===2,'fake transport receives two individually addressed annual invoices');
ok(count(array_unique(array_column($calls,'to')))===2&&!in_array('child@example.invalid',array_column($calls,'to'),true),'family children never receive separate contribution mail');
ok(str_starts_with($calls[0]['attachments'][0]['bytes'],'%PDF-')&&str_contains($calls[0]['html'],'Eure Beitragsrechnung'),'actual issued PDF and shared mail design supplied to fake transport');
ok($worker->dispatch('https://verein.example.invalid',$fake,'2026-01-02')===0,'sent invoice never retries automatically');
ok($worker->preview('2026-02-01')['reminders']===[],'no reminder on the payment deadline itself');
ok(count($worker->preview('2026-02-02')['reminders'])===2,'first overdue day offers reminders');
$queued=$worker->run('2026-02-02',true);ok($queued['queued']===2,'first reminder cycle queues once per entry');
ok($worker->run('2026-02-03',true)['queued']===0,'pending cycle blocks duplicate and parallel cycles');
$account=$finance->createAccount('Synthetic bank','offline','0','2026-01-01');
$transaction=$finance->createTransaction(['account'=>$account,'booked_on'=>'2026-02-10','direction'=>'income','amount'=>'20','description'=>'Synthetic partial payment','counterparty'=>'Test single'],$key());$finance->allocate($transaction,1,$single,(int)$finance->entry($single)['version'],'20',$key());
$finance->cancel($payer,(int)$finance->entry($payer)['version']);
$db->exec("UPDATE memberships SET status='ehemalig',ends_on='2026-01-20' WHERE contact_id='single'");
ok($worker->dispatch('https://verein.example.invalid',$fake,'2026-02-20')===1,'late dispatch rechecks cancellations and keeps existing debt after membership ends');
$last=$calls[count($calls)-1];ok(str_contains($last['text'],'Offener Betrag: 28,00 €')&&!str_contains($last['text'],'Offener Betrag: 48,00 €'),'reminder uses current remaining amount after partial payment');
ok((int)$db->query("SELECT sent_remaining_cents FROM contribution_deliveries WHERE entry_id=".$db->quote($single)." AND type='reminder' AND status='sent'")->fetchColumn()===2800,'sent remaining amount is recorded');
ok($worker->preview('2026-03-01')['reminders']===[],'new due-date window cannot bypass 30 days since actual late send');
ok(count($worker->preview('2026-03-23')['reminders'])===1,'next reminder only after at least 30 actual days');
$worker->run('2026-03-23',true);$before=count($calls);
ok($worker->dispatch('https://verein.example.invalid',static function(){throw new RuntimeException('ambiguous SMTP outcome');},'2026-03-23')===0,'ambiguous transport is not reported as sent');
ok((int)$db->query("SELECT COUNT(*) FROM contribution_deliveries WHERE status='uncertain'")->fetchColumn()===1,'ambiguous SMTP outcome remains uncertain');
ok($worker->dispatch('https://verein.example.invalid',$fake,'2026-04-30')===0&&count($calls)===$before,'uncertain SMTP delivery is never retried automatically');
ok($worker->run('2026-04-30',true)['queued']===0,'uncertain previous cycle blocks every later reminder cycle');

$late=(new Finance($db,'finance-only'))->createAnnualContribution('late',2026,'','2026-02-01');(new ContributionInvoices($db,'manager'))->issue($late);
$queueWorker=new ContributionReminders($db,'queue');ok($queueWorker->run('2026-03-03',true)['queued']===1,'separate financial actor can queue eligible invoice reminder');
$db->exec("DELETE FROM actor_capabilities WHERE actor_id='queue'");
ok($worker->dispatch('https://verein.example.invalid',$fake,'2026-03-03')===0,'revoked financial rights of original requester cancel queued delivery');
ok((int)$db->query("SELECT COUNT(*) FROM contribution_deliveries WHERE actor_id='queue' AND status='skipped'")->fetchColumn()===1,'revoked delivery records skip reason');
$worker->run('2026-04-05',true);$db->exec("UPDATE contacts SET email='changed@example.invalid' WHERE id='late'");
ok($worker->dispatch('https://verein.example.invalid',$fake,'2026-04-05')===0,'changed payer address is not silently used for already approved delivery');
$worker->run('2026-05-06',true);$finance->recordPayment($late,(int)$finance->entry($late)['version'],$account,'2026-05-06');
ok($worker->dispatch('https://verein.example.invalid',$fake,'2026-05-06')===0,'payment after queue but before dispatch prevents reminder');
$db->exec("INSERT INTO contacts(id,club_id,kind,name,email,address) VALUES('welcome-payer','a','person','Welcome Test','welcome@example.invalid','Testweg 3, 00000 Musterort');INSERT INTO memberships(id,club_id,contact_id,member_number,status,starts_on) VALUES('m-welcome','a','welcome-payer','T99','aktiv','2025-01-01')");
$welcomeEntry=$finance->createAnnualContribution('welcome-payer',2026,'','2026-02-01');(new ContributionInvoices($db,'manager'))->issue($welcomeEntry);
$db->prepare("INSERT INTO membership_applications(id,club_id,request_key,status,answers,configuration,consent_snapshot,configuration_version,submitted_at,reviewed_at,reviewed_by,contact_id) VALUES('welcome-app','a',?,'accepted',?,'{}','{}',1,'2025-12-01','2025-12-02','manager','welcome-payer')")->execute([$key(),json_encode(['membership_type'=>'single'])]);
$db->prepare("INSERT INTO membership_welcome(club_id,application_id,contact_id,membership_id,email,entry_id,payload,welcome_status,invoice_status,created_at) VALUES('a','welcome-app','welcome-payer','m-welcome','welcome@example.invalid',?,'{}','sent','waiting','2026-02-01')")->execute([$welcomeEntry]);
$worker->run('2026-01-01',true);
ok((int)$db->query('SELECT COUNT(*) FROM contribution_deliveries WHERE entry_id='.$db->quote($welcomeEntry))->fetchColumn()===0,'annual delivery never duplicates first invoice handled by welcome flow');
ok($worker->preview('2026-03-03')['reminders']===[],'waiting welcome invoice prevents reminder before initial invoice delivery');
$db->exec("UPDATE membership_welcome SET invoice_status='sent',invoice_sent_at='2026-03-01T23:59:59Z' WHERE application_id='welcome-app'");
ok($worker->preview('2026-03-20')['reminders']===[],'actual welcome-invoice send also starts the minimum 30-day interval');
ok(count($worker->preview('2026-04-03')['reminders'])===1,'welcome invoice becomes reminder eligible after full interval');
ok($worker->preview('2027-02-02')['reminders']===[],'reminders never carry old-year debt into the new current-year run');
denied(fn()=>$worker->preview('2026-02-30'),'invalid scheduler day rejected');
ok(\Kulturhus\Verein\Tests\MySqlFixture::integrity($db)==='ok'&&\Kulturhus\Verein\Tests\MySqlFixture::foreignKeyErrors($db)===[],'billing and outbox foreign keys remain intact');
echo "$n contribution reminder checks passed; fake transport only\n";
